select jsonb_build_object(
'counts',jsonb_build_object('values',(select count(*) from private.vocabulary_learning_value_versions),'bindings',(select count(*) from private.vocabulary_learning_value_bindings),'scopes',(select count(*) from private.vocabulary_library_scopes where dataset_id='c1011001-6a01-4b01-8c01-000000000001'),'rows',(select count(*) from private.vocabulary_library_scope_rows r join private.vocabulary_library_scopes s on s.id=r.scope_id where s.dataset_id='c1011001-6a01-4b01-8c01-000000000001'),'fingerprints',(select count(*) from private.vocabulary_library_row_fingerprints f join private.vocabulary_library_scopes s on s.id=f.scope_id where s.dataset_id='c1011001-6a01-4b01-8c01-000000000001')),
'scopes',(select jsonb_agg(jsonb_build_object('id',s.id,'key',s.scope_key,'version',s.version,'resources',r.resources,'bindingMatches',b.selection_id=v.selection_id,'sourceHashMatches',b.payload#>>'{originalHashes,entrySnapshotHash}'=private.reviewed_exam_sha256_v1(to_jsonb(e)),'valueBytes',pg_column_size(v.payload),'bindingBytes',pg_column_size(b.payload)) order by s.scope_key)
from private.vocabulary_library_scopes s join private.vocabulary_library_scope_rows r on r.scope_id=s.id join public.vocab_entries e on e.id=r.source_entry_id join private.vocabulary_learning_value_versions v on v.selection_id=(r.resources#>>'{selected,selectionId}')::uuid join private.vocabulary_learning_value_bindings b on b.binding_id=(r.resources#>>'{selectionBinding,bindingId}')::uuid where s.dataset_id='c1011001-6a01-4b01-8c01-000000000001'),
'hashes',jsonb_build_object('values',(select md5(string_agg(to_jsonb(v)::text,'' order by v.selection_id)) from private.vocabulary_learning_value_versions v),'bindings',(select md5(string_agg(to_jsonb(b)::text,'' order by b.binding_id)) from private.vocabulary_learning_value_bindings b),'scopeRows',(select md5(string_agg(to_jsonb(r)::text,'' order by r.scope_id)) from private.vocabulary_library_scope_rows r join private.vocabulary_library_scopes s on s.id=r.scope_id where s.dataset_id='c1011001-6a01-4b01-8c01-000000000001'))) result;
